// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface TeaToken {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function swapAndLiquifyEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x5e18Be2A7cE626B33C539919EAca06303f1Db568;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup required
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner address
        address owner = TeaToken(TARGET).owner();

        // Impersonate the owner and call the function
        vm.prank(owner);
        TeaToken(TARGET).setSwapAndLiquifyEnabled(false);

        // Verify the state change
        bool enabled = TeaToken(TARGET).swapAndLiquifyEnabled();
        assertEq(enabled, false, "swapAndLiquifyEnabled should be false");
        assertEq(enabled, false, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
